### Description

Hello guys!

Whenever I make an MCP Client tool call than it getting back with this error message:

> Error: Error executing tool google_calendar_find_event: Attempted to send a request from a closed client

What is the problem here? I am trying to integrate my Zapier MCP there.

### Code example

```
import { openai } from "@ai-sdk/openai"
import { experimental_createMCPClient, streamText } from "ai"

// Allow streaming responses up to 30 seconds
export const maxDuration = 30

function errorHandler(error: unknown) {
  if (error == null) {
    return 'unknown error';
  }

  if (typeof error === 'string') {
    return error;
  }

  if (error instanceof Error) {
    return error.message;
  }

  return JSON.stringify(error);
}

export async function POST(req: Request) {
  const { messages } = await req.json()

  // Create MCP client to connect to Zapier Actions
  const mcpClient = await experimental_createMCPClient({
    transport: {
      type: "sse",
      url: "https://actions.zapier.com/mcp/aaaaaaaaaaa/sse",
    },
  })

  try {
    // Get tools from the MCP server
    const zapierTools = await mcpClient.tools()

    console.log(zapierTools)

    // Stream response using OpenAI model with Zapier tools
    const result = streamText({
      model: openai("gpt-4o"),
      messages,
      tools: zapierTools,
    })

    return result.toDataStreamResponse({
      getErrorMessage: errorHandler,
    });
  } finally {
    // Always close the MCP client to prevent resource leaks
    await mcpClient.close()
  }
}


```

